/// FFI-facing link preview for a URL embedded in a message.
/// Generated by the SENDER and carried with the message. Receivers render from
/// these fields and NEVER request the previewed URL, which is a privacy property,
/// not a cache optimization.
class LinkPreviewRef {
  /// The URL that was previewed.
  final String url;

  /// og:title or <title> fallback. Already truncated by the sender.
  final String title;

  /// og:description or meta description. Already truncated by the sender.
  final String description;

  /// Display domain parsed from the URL (e.g. "github.com").
  final String domain;

  /// og:site_name if present. Empty string = fall back to domain in UI.
  final String siteName;

  /// Base64-encoded lossy WebP thumbnail (Q=50, max dim 400px).
  /// None when no og:image was found or the image fetch failed.
  final String? thumbWebpB64;

  /// Thumbnail width after resize.
  final int? thumbW;

  /// Thumbnail height after resize.
  final int? thumbH;

  /// `"large"` = social-post layout (image on top), `None` = compact row.
  final String? kind;

  /// Post author line, e.g. `"Jane Doe (@jane)"`. Social adapters only.
  final String? author;

  /// Where the post's video lives: a direct `.mp4`/`.webm` that plays inline on tap,
  /// or the media page. Never fetched to render the card, never autoplayed.
  final String? videoUrl;

  /// Video width, for the card's aspect ratio.
  final int? videoW;

  /// Video height, for the card's aspect ratio.
  final int? videoH;

  const LinkPreviewRef({
    required this.url,
    required this.title,
    required this.description,
    required this.domain,
    required this.siteName,
    this.thumbWebpB64,
    this.thumbW,
    this.thumbH,
    this.kind,
    this.author,
    this.videoUrl,
    this.videoW,
    this.videoH,
  });

  @override
  int get hashCode =>
      url.hashCode ^
      title.hashCode ^
      description.hashCode ^
      domain.hashCode ^
      siteName.hashCode ^
      thumbWebpB64.hashCode ^
      thumbW.hashCode ^
      thumbH.hashCode ^
      kind.hashCode ^
      author.hashCode ^
      videoUrl.hashCode ^
      videoW.hashCode ^
      videoH.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is LinkPreviewRef &&
          runtimeType == other.runtimeType &&
          url == other.url &&
          title == other.title &&
          description == other.description &&
          domain == other.domain &&
          siteName == other.siteName &&
          thumbWebpB64 == other.thumbWebpB64 &&
          thumbW == other.thumbW &&
          thumbH == other.thumbH &&
          kind == other.kind &&
          author == other.author &&
          videoUrl == other.videoUrl &&
          videoW == other.videoW &&
          videoH == other.videoH;
}

/// Result of a versioned Message Proof verification — see
/// [`verify_message_proof_v2`].
class MessageProofV2 {
  final bool hasSignature;
  final bool valid;

  /// 2 = verified against the v2 payload, 0 = did not verify. `1` (legacy v1, text
  /// only) is no longer produced; the variant stays out of the contract rather than
  /// out of the range so old Dart builds that switch on `== 2` keep behaving.
  final int sigVersion;

  /// The canonical v2 payload string, displayed and exported whether or not it
  /// verified.
  final String canonicalPayload;

  /// The row's signed fields, for the exported proof JSON.
  final String text;
  final PlatformInt64 timestampMs;
  final PlatformInt64? editedAt;
  final String? replyTo;
  final String? fileId;
  final PlatformInt64? orderUs;
  final String? lpDigest;
  final String? signatureB64;
  final String? publicKeyB64;

  const MessageProofV2({
    required this.hasSignature,
    required this.valid,
    required this.sigVersion,
    required this.canonicalPayload,
    required this.text,
    required this.timestampMs,
    this.editedAt,
    this.replyTo,
    this.fileId,
    this.orderUs,
    this.lpDigest,
    this.signatureB64,
    this.publicKeyB64,
  });

  @override
  int get hashCode =>
      hasSignature.hashCode ^
      valid.hashCode ^
      sigVersion.hashCode ^
      canonicalPayload.hashCode ^
      text.hashCode ^
      timestampMs.hashCode ^
      editedAt.hashCode ^
      replyTo.hashCode ^
      fileId.hashCode ^
      orderUs.hashCode ^
      lpDigest.hashCode ^
      signatureB64.hashCode ^
      publicKeyB64.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MessageProofV2 &&
          runtimeType == other.runtimeType &&
          hasSignature == other.hasSignature &&
          valid == other.valid &&
          sigVersion == other.sigVersion &&
          canonicalPayload == other.canonicalPayload &&
          text == other.text &&
          timestampMs == other.timestampMs &&
          editedAt == other.editedAt &&
          replyTo == other.replyTo &&
          fileId == other.fileId &&
          orderUs == other.orderUs &&
          lpDigest == other.lpDigest &&
          signatureB64 == other.signatureB64 &&
          publicKeyB64 == other.publicKeyB64;
}

