/// A piece of imported shop art and who made it.
class OwnedArt {
  final String hash;
  final String role;
  final String itemId;
  final String title;
  final String artistName;
  final String artistSlug;
  final String artistUrl;
  final String license;

  /// Unix milliseconds.
  final PlatformInt64 importedAt;

  const OwnedArt({
    required this.hash,
    required this.role,
    required this.itemId,
    required this.title,
    required this.artistName,
    required this.artistSlug,
    required this.artistUrl,
    required this.license,
    required this.importedAt,
  });

  @override
  int get hashCode =>
      hash.hashCode ^
      role.hashCode ^
      itemId.hashCode ^
      title.hashCode ^
      artistName.hashCode ^
      artistSlug.hashCode ^
      artistUrl.hashCode ^
      license.hashCode ^
      importedAt.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is OwnedArt &&
          runtimeType == other.runtimeType &&
          hash == other.hash &&
          role == other.role &&
          itemId == other.itemId &&
          title == other.title &&
          artistName == other.artistName &&
          artistSlug == other.artistSlug &&
          artistUrl == other.artistUrl &&
          license == other.license &&
          importedAt == other.importedAt;
}

/// A frame blob that has been processed and cached locally, ready to be
/// named in `update_profile(avatar_frame: ...)`.
class ProcessedFrame {
  /// 64-hex SHA-256 of the processed bytes: the frame's identity, and what rides the
  /// profile announce.
  final String hash;
  final bool animated;

  /// The processed bytes, so the picker previews exactly what everyone else sees.
  final Uint8List bytes;

  const ProcessedFrame({
    required this.hash,
    required this.animated,
    required this.bytes,
  });

  @override
  int get hashCode => hash.hashCode ^ animated.hashCode ^ bytes.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProcessedFrame &&
          runtimeType == other.runtimeType &&
          hash == other.hash &&
          animated == other.animated &&
          bytes == other.bytes;
}

/// An animated avatar or banner that has been processed and cached locally,
/// ready to be named in `update_profile(avatar_anim: ...)`.
class ProcessedProfileMedia {
  /// 64-hex SHA-256 of the ANIMATED bytes: the identity that rides the announce and
  /// what peers pull on the asset rail.
  final String hash;

  /// The animated WebP, so the picker previews exactly what everyone else sees.
  final Uint8List bytes;

  /// The STILL companion (frame 0, same ceiling), which the caller must pass as
  /// `avatar_bytes` / `banner_bytes`: it stays inside the pushed profile so old
  /// clients and the guest thumb still see a face.
  final Uint8List still;

  const ProcessedProfileMedia({
    required this.hash,
    required this.bytes,
    required this.still,
  });

  @override
  int get hashCode => hash.hashCode ^ bytes.hashCode ^ still.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProcessedProfileMedia &&
          runtimeType == other.runtimeType &&
          hash == other.hash &&
          bytes == other.bytes &&
          still == other.still;
}

