/// FFI-facing video thumbnail back-reference.
/// Present on a `FileHeaderReceived` when the file is a thumbnail for a video in
/// the vault; Dart renders the play overlay and calls `vault_download_file(cid)`.
class VideoThumbRef {
  /// Vault content_id (sha256 of ciphertext) of the underlying video.
  final String cid;

  /// Original video file extension (mp4, webm, mkv, ...).
  final String ext;

  /// Original video file name (used as the default for the Save As dialog).
  final String name;

  /// Video size in bytes.
  final BigInt size;

  /// Video duration in milliseconds.
  final int durMs;

  const VideoThumbRef({
    required this.cid,
    required this.ext,
    required this.name,
    required this.size,
    required this.durMs,
  });

  @override
  int get hashCode =>
      cid.hashCode ^
      ext.hashCode ^
      name.hashCode ^
      size.hashCode ^
      durMs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VideoThumbRef &&
          runtimeType == other.runtimeType &&
          cid == other.cid &&
          ext == other.ext &&
          name == other.name &&
          size == other.size &&
          durMs == other.durMs;
}
